'use strict';
const state={lang:localStorage.getItem('vm-design-language')==='en'?'en':'is',industry:0,request:null};
const T=(is,en)=>state.lang==='is'?is:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
const circle='<span class="circle" aria-hidden="true">↗</span>';
const productKeys=['labels','foil','film','bottles','paper'];
const products={
 labels:{name:['Límmiðar','Labels'],short:['Pappír, plast og álefni.','Paper, film and foil.'],lead:['Límmiðar sem henta yfirborði og notkun.','Labels chosen for the surface and the task.'],body:['Útlitið er aðeins hluti af valinu. Umbúðir, hitastig, raki og ásetning skipta líka máli. Við aðstoðum við val á efni, prentaðferð og frágangi.','Appearance is only part of the choice. The container, temperature, moisture and application method matter too. We help you choose materials, print methods and finishes.'],tags:[['Vörumerkingar','Product labels'],['Rúllumiðar','Roll labels'],['Stafræn prentun','Digital printing']],specs:[[['Efni','Materials'],['Pappír, plastefni og álefni eftir notkun.','Paper, film and foil, according to the application.']],[['Frágangur','Finishes'],['Lökkun og laminering eftir útfærslu.','Varnishing and lamination, depending on the specification.']],[['Ásetning','Application'],['Handvirk eða vélræn. Staðfesta þarf upprúllun og kjarna.','Manual or machine. Unwind direction and core must be confirmed.']],[['Prentaðferð','Print method'],['Stafræn eða hefðbundin prentun. Við aðstoðum við valið.','Digital or conventional printing. We help you choose.']]]},
 foil:{name:['Állok og álfilmur','Foil lids & films'],short:['Áprentuð lok og þynnur.','Printed lids and foils.'],lead:['Frágangur sem tekur mið af umbúðunum.','A finish designed around the container.'],body:['Segðu okkur frá ílátinu og notkuninni. Við förum yfir stærð, efnisval og prentun áður en útfærsla og hæfi eru staðfest.','Tell us about the container and how it is used. We review dimensions, material and print before confirming the specification and suitability.'],tags:[['Áprentuð lok','Printed lids'],['Stönsun','Die cutting'],['Umbúðir','Packaging']],specs:[[['Notkun','Application'],['Lok og álfilmur fyrir tilgreindar umbúðir.','Lids and foil films for specified containers.']],[['Stærð og lögun','Size & shape'],['Samkvæmt stansformi og kröfum íláts.','According to the dieline and container requirements.']],[['Prentun','Printing'],['Útlit og litir skilgreind með prentgögnum.','Appearance and colours defined by the artwork.']],[['Staðfesting','Confirmation'],['Hæfi, efni og tæknikröfur yfirfarnar fyrir framleiðslu.','Suitability, materials and technical requirements reviewed before production.']]]},
 film:{name:['Pökkunarfilma','Packaging film'],short:['Áprentuð filma fyrir umbúðir.','Printed film for packaging.'],lead:['Vörumerkið fylgir umbúðunum.','Your identity, carried by the packaging.'],body:['Áprentuð pökkunarfilma tengir útlit vörunnar við kröfur umbúða og framleiðslu. Lýstu notkun, stærð og búnaði svo við getum rætt rétta útfærslu.','Printed packaging film connects your product’s identity with packaging and production requirements. Describe the use, dimensions and equipment so we can discuss the right specification.'],tags:[['Áprentun','Printing'],['Filmur','Films'],['Framleiðsla','Production']],specs:[[['Notkun','Use'],['Umbúðir og vörutegund skilgreind í beiðni.','Packaging application and product defined in the request.']],[['Stærðir','Dimensions'],['Breidd og endurtekning eftir útfærslu.','Width and repeat according to the specification.']],[['Búnaður','Equipment'],['Upplýsingar um pökkunarvél eftir þörfum.','Packaging-machine details where relevant.']],[['Efnisval','Materials'],['Val og hæfi staðfest með framleiðslu.','Selection and suitability confirmed with production.']]]},
 cards:{name:['Plastkort','Plastic cards'],short:['Kort fyrir ólík tilefni.','Cards for different purposes.'],lead:['Lítið format. Skýr ásýnd.','A small format. A clear identity.'],body:['Gjafakort, aðildarkort og önnur plastkort hafa ólíka notkun og tæknilegar þarfir. Við förum yfir útlit, upplýsingar og útfærslu með þér.','Gift cards, membership cards and other plastic cards have different uses and technical needs. We review appearance, information and specification with you.'],tags:[['Gjafakort','Gift cards'],['Aðildarkort','Membership cards'],['Áprentun','Custom print']],specs:[[['Tilgangur','Purpose'],['Gjafir, aðild og önnur kortanotkun.','Gifts, membership and other card applications.']],[['Upplýsingar','Information'],['Fastar eða breytilegar upplýsingar eftir verkefni.','Fixed or variable information depending on the project.']],[['Tækni','Technology'],['Kröfur um lestur og notkun skilgreindar í samtali.','Reader and usage requirements defined in consultation.']],[['Prentgögn','Artwork'],['Útlit og gögn samþykkt fyrir framleiðslu.','Design and data approved before production.']]]},
 tickets:{name:['Miðar og spjöld','Tickets & passes'],short:['Aðgöngumiðar og brottfararspjöld.','Admission tickets and boarding passes.'],lead:['Skýrar upplýsingar. Réttur aðgangur.','Clear information. The right access.'],body:['Aðgöngumiðar og brottfararspjöld þurfa að henta notkun, lestri og afgreiðslu. Segðu okkur frá viðburði eða ferli, magni og upplýsingum sem þurfa að birtast.','Tickets and boarding passes need to work with their use, reading and handling. Tell us about the event or process, quantities and the information that needs to appear.'],tags:[['Viðburðir','Events'],['Aðgöngumiðar','Admission tickets'],['Brottfararspjöld','Boarding passes']],specs:[[['Notkun','Use'],['Viðburðir, aðgangur eða brottför.','Events, access or departures.']],[['Upplýsingar','Information'],['Númer, texti og breytileg gögn eftir þörfum.','Numbers, text and variable information where needed.']],[['Format','Format'],['Stærð og frágangur samkvæmt verkefni.','Size and finishing according to the project.']],[['Lestrarbúnaður','Reading equipment'],['Samhæfni staðfest þar sem við á.','Compatibility confirmed where applicable.']]]}
};
products.bottles={name:['Flöskur','Bottles'],short:['Fjölbreytt form og efni fyrir ólíkar þarfir.','A range of forms and materials for different needs.'],lead:['Réttar umbúðir fyrir hverja vöru.','The right packaging for every product.'],body:['Skoðaðu möguleika í flöskum og merkingum. Efni, lögun og frágangur taka mið af vörunni, notkun hennar og ásýnd vörumerkisins. Við vinnum með viðskiptavinum að útfærslu sem sameinar útlit og notagildi.','Explore possibilities in bottles and labelling. Materials, shape and finishing are guided by the product, its use and brand identity. We work with clients on solutions that bring appearance and function together.'],tags:[['Plastflöskur','Plastic bottles'],['Umbúðir','Packaging'],['Merkingar','Labelling']],specs:[[['Efni','Materials'],['Efnisval tekur mið af notkun.','Materials chosen to suit the application.']],[['Lögun','Shape'],['Ólík form og stærðir eftir verkefni.','Different forms and sizes to suit the project.']],[['Ásýnd','Identity'],['Merkingar og frágangur í takt við vörumerkið.','Labelling and finishing aligned with the brand.']]]};
products.paper={name:['Pappír / karton','Paper / card'],short:['Prentun og frágangur á pappír og kartoni.','Printing and finishing on paper and card.'],lead:['Áferð, form og frágangur.','Texture, form and finish.'],body:['Við vinnum með pappír og karton í fjölbreyttum verkefnum þar sem efnisval, prentun og frágangur móta heildarásýndina. Hver útfærsla tekur mið af þörfum viðskiptavinarins og ásýnd vörumerkisins.','We work with paper and card across projects where material, printing and finishing shape the final impression. Each solution reflects the client’s needs and brand identity.'],tags:[['Pappír','Paper'],['Karton','Card'],['Prentun','Printing']],specs:[[['Efni','Materials'],['Pappír og karton eftir verkefni.','Paper and card selected for the project.']],[['Áferð','Texture'],['Efnisval í takt við ásýnd og notkun.','Materials aligned with appearance and purpose.']],[['Frágangur','Finishing'],['Prentun og frágangur aðlöguð verkefninu.','Printing and finishing tailored to the project.']]]};
const pair=p=>p[state.lang==='is'?0:1];
let artSerial=0;
function productArt(key){
 const id=`art-${key}-${artSerial++}`;
 const defs=`<defs><linearGradient id="${id}-metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fcffff"/><stop offset=".25" stop-color="#98aebc"/><stop offset=".43" stop-color="#f7ffff"/><stop offset=".65" stop-color="#7a94a6"/><stop offset=".85" stop-color="#dbe6ed"/><stop offset="1" stop-color="#506e84"/></linearGradient><linearGradient id="${id}-film"><stop stop-color="#cad3d9" stop-opacity=".65"/><stop offset=".28" stop-color="#fff" stop-opacity=".85"/><stop offset=".54" stop-color="#8ca0b0" stop-opacity=".62"/><stop offset=".8" stop-color="#eee" stop-opacity=".9"/><stop offset="1" stop-color="#849bad" stop-opacity=".7"/></linearGradient><filter id="${id}-shadow"><feGaussianBlur stdDeviation="9"/></filter></defs>`;
 let art='';
 if(key==='foil')art=`<ellipse cx="236" cy="306" rx="141" ry="19" fill="#526779" opacity=".2" filter="url(#${id}-shadow)"/><g transform="rotate(-13 240 200)"><ellipse cx="245" cy="223" rx="130" ry="78" fill="#6e879b"/><ellipse cx="245" cy="216" rx="130" ry="77" fill="url(#${id}-metal)" stroke="#c1d2db" stroke-width="2"/><ellipse cx="245" cy="212" rx="114" ry="63" fill="#143d56"/><path d="M134 225 Q250 245 329 162 Q359 199 351 226 Q253 290 134 225Z" fill="#234f70"/><ellipse cx="245" cy="209" rx="100" ry="48" fill="none" stroke="#d7c18e" stroke-width="1.4"/><path d="M199 183v39q0 21 26 21t26-21v-39" fill="none" stroke="#e8e1c9" stroke-width="5"/><path d="M264 177v43q0 28-37 32" fill="none" stroke="#e8e1c9" stroke-width="3"/><path d="M143 250l-22 33 38 6 12-28" fill="url(#${id}-metal)"/></g><g transform="translate(-60 -29) scale(.73)"><ellipse cx="225" cy="142" rx="130" ry="77" fill="url(#${id}-metal)" stroke="#cfdae1"/><ellipse cx="225" cy="142" rx="116" ry="63" fill="#eee9db"/><path d="M130 158Q218 135 309 186" fill="none" stroke="#163e57" stroke-width="24"/><circle cx="262" cy="124" r="25" fill="#bc9954"/></g>`;
 else if(key==='film')art=`<ellipse cx="245" cy="310" rx="140" ry="23" fill="#6e6c60" opacity=".16" filter="url(#${id}-shadow)"/><g transform="rotate(-13 225 198)"><path d="M139 122L330 122 330 264 139 264Z" fill="url(#${id}-film)" stroke="#b7c2c7"/><path d="M177 133Q225 216 289 140V262H177Z" fill="#214d6a" opacity=".76"/><ellipse cx="144" cy="193" rx="39" ry="73" fill="#b3c2cb"/><ellipse cx="137" cy="193" rx="39" ry="73" fill="url(#${id}-film)" stroke="#e8e9e4" stroke-width="3"/><ellipse cx="137" cy="193" rx="15" ry="36" fill="#ac9373"/><ellipse cx="137" cy="193" rx="10" ry="31" fill="#5e5142"/><path d="M291 143Q325 183 400 280L256 308Q215 247 239 178" fill="url(#${id}-film)" stroke="#dce2e2"/><path d="M292 155Q316 224 340 295" fill="none" stroke="#245678" stroke-width="50" opacity=".67"/><path d="M267 186Q286 230 303 299" fill="none" stroke="#efece1" stroke-width="5"/><ellipse cx="330" cy="193" rx="37" ry="71" fill="none" stroke="#e8e9e4" stroke-width="2"/></g>`;
 else if(key==='cards')art=`<ellipse cx="249" cy="296" rx="145" ry="16" fill="#3f5750" opacity=".18" filter="url(#${id}-shadow)"/><g transform="translate(72 136) rotate(-12)"><rect width="263" height="166" rx="9" fill="#193e57"/><rect x="14" y="16" width="235" height="133" rx="2" fill="none" stroke="#b59b66"/><path d="M25 102Q110 174 226 29" fill="none" stroke="#355f71" stroke-width="52"/><text x="27" y="55" font-family="Georgia" font-size="24" fill="#f4f0e5">01</text><g fill="#d6c68f"><rect x="190" y="119" width="6" height="11"/><rect x="200" y="119" width="2" height="11"/><rect x="206" y="119" width="8" height="11"/><rect x="218" y="119" width="4" height="11"/></g></g><g transform="translate(110 72) rotate(9)"><rect width="263" height="166" rx="9" fill="#f5f0df"/><path d="M144 0Q105 90 263 146V0" fill="#143e57"/><circle cx="188" cy="77" r="25" fill="#c7a65e"/><path d="M25 60h72m-72 13h59m-59 45h96" stroke="#516368" stroke-width="2"/></g>`;
 else art=`<ellipse cx="235" cy="313" rx="138" ry="16" fill="#64616d" opacity=".16" filter="url(#${id}-shadow)"/><g transform="translate(54 138) rotate(-8)"><path d="M0 0H328V143H0V87q18 0 18-15T0 57Z" fill="#163e57"/><path d="M252 7v129" stroke="#dde4e5" stroke-width="1" stroke-dasharray="3 4"/><path d="M29 31h107m-107 13h82" stroke="#b2c6cb" stroke-width="2"/><text x="27" y="115" font-family="Georgia" font-size="40" fill="#f2eee1">01</text><g fill="#e8e3d2"><rect x="272" y="31" width="4" height="77"/><rect x="281" y="31" width="2" height="77"/><rect x="287" y="31" width="7" height="77"/><rect x="298" y="31" width="3" height="77"/><rect x="305" y="31" width="6" height="77"/></g></g><g transform="translate(118 53) rotate(10)"><path d="M0 0H305V133H0V83q16 0 16-16T0 51Z" fill="#f1ecdc"/><path d="M230 7v118" stroke="#6e7d7e" stroke-width="1" stroke-dasharray="3 4"/><circle cx="178" cy="67" r="43" fill="#c6a364"/><path d="M95 0q-12 61 37 133h56Q120 62 144 0" fill="#214c69"/><path d="M26 33h41m-41 10h31" stroke="#3d5c6b" stroke-width="2"/></g>`;
 return `<svg viewBox="0 0 480 370" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${defs}${art}</svg>`;
}
function productPicture(key){if(key==='paper')return `<img src="assets/paper-card-editorial.png" alt="${T('Myndræn framsetning á pappír og kartoni','Illustrative studio photograph of paper and card')}" loading="lazy" width="1448" height="1086">`;if(key==='bottles')return `<img src="assets/bottles-editorial.png" alt="${T('Myndræn framsetning á hvítum plastflöskum','Illustrative studio photograph of white plastic bottles')}" loading="lazy" width="1536" height="1024">`;return key==='labels'?`<img src="assets/packaging-editorial.png" alt="${T('Unnið að hönnun vörumerkingar','Product label design in progress')}" loading="lazy" width="2744" height="1528">`:productArt(key);}
function productCard(key,i,large=false){const p=products[key];return `<a class="product-card ${large?'large':''}" href="#product/${key}"><div class="product-image ${key}">${productPicture(key)}</div><div class="card-content"><div><h3>${pair(p.name)}</h3><p>${pair(p.short)}</p></div>${circle}</div></a>`;}
const menuItems=()=>[[T('Vörur','Products'),'products'],[T('Atvinnugreinar','Industries'),'industries'],[T('Gæði','Quality'),'quality'],[T('Prentgögn','Artwork'),'artwork'],[T('Um okkur','About'),'about']];
function header(){
 document.getElementById('header').innerHTML=`<div class="utility container"><span>${T('Íslensk framleiðsla · Frá 1962','Icelandic production · Since 1962')}</span><div class="utility-links"><button data-reorder>${T('Endurpanta','Repeat order')} ↗</button><a href="#artwork">${T('Skila prentgögnum','Artwork delivery')} ↗</a></div></div><header class="site-header"><div class="nav-row container"><a class="brand" href="#home" aria-label="${T('Vörumerking forsíða','Vörumerking homepage')}"><img src="assets/logo-horizontal-blue.svg" alt="Vörumerking" width="510" height="77"></a><nav class="nav-links" aria-label="${T('Aðalvalmynd','Main navigation')}">${menuItems().map(([name,key])=>`<a href="#${key}">${name}</a>`).join('')}</nav><div class="nav-actions"><button class="language" data-language aria-label="${T('Skipta yfir á ensku','Switch to Icelandic')}"><span class="${state.lang==='is'?'active':''}">IS</span> / <span class="${state.lang==='en'?'active':''}">EN</span></button><button class="pill" data-quote>${T('Fá tilboð','Request a quote')}${arrow}</button><button class="menu-trigger" data-menu aria-label="${T('Opna valmynd','Open menu')}">☰</button></div></div></header>`;
}
function footer(){
 document.getElementById('footer').innerHTML=`<footer class="contact-footer" id="contact"><div class="container"><div class="contact-top"><div><div class="eyebrow">${T('Tökum næsta skref','Let’s take the next step')}</div><h2 class="serif">${T('Byrjum á<br>vörunni þinni.','Let’s start with<br>your product.')}</h2></div><div><button class="pill light" data-quote>${T('Segðu okkur frá verkefninu','Tell us about your project')}${arrow}</button></div></div><div class="footer-bottom"><div><a class="footer-brand" href="#home"><img src="assets/logo-horizontal-white.svg" alt="Vörumerking" width="510" height="77"></a><p class="footer-description">${T('Merkingar, prentun og umbúðir. Þekking og persónuleg ráðgjöf fylgja verkinu.','Labels, printing and packaging. Expertise and personal advice, from start to finish.')}</p></div><div><h3>${T('Hafa samband','Contact')}</h3><p><a href="tel:+3544142500">+354 414 2500</a><br><a href="mailto:vorumerking@vorumerking.is">vorumerking@vorumerking.is</a></p><p>Suðurhraun 6<br>210 ${T('Garðabær','Garðabær, Iceland')}</p></div><div><h3>${T('Gagnlegar leiðir','Useful links')}</h3><div class="footer-link-list"><a href="#products">${T('Vörur og lausnir','Products and solutions')}</a><a href="#artwork">${T('Prentgögn og aðstoð','Artwork and help')}</a><a href="#quality">${T('Gæði og ferli','Quality and process')}</a><button class="footer-reorder" data-reorder style="color:inherit;background:none;border:0;text-align:left;padding:0;font:inherit">${T('Endurpanta','Repeat order')}</button></div></div></div><div class="footer-legal"><span>© 2026 Vörumerking · ${T('Hönnunartillaga','Design concept')}</span><div class="footer-legal-links"><button data-info="privacy">${T('Persónuvernd','Privacy')}</button><button data-info="design">${T('Um hönnunina','About the design')}</button><a href="https://www.vorumerking.is/" target="_blank" rel="noopener">${T('Núverandi vefur','Current website')} ↗</a></div></div></div></footer>`;
}
const industries=[
 {name:['Matvæli og drykkir','Food & beverages'],body:['Umbúðir, hitastig, raki og ásetning ráða miklu um valið. Við förum með þér yfir merkingar, állok og filmur fyrir viðkomandi notkun.','Containers, temperature, moisture and application all guide the choice. We discuss labels, foil lids and films for the specific use.'],action:['Ræða matvælaverkefni','Discuss a food project']},
 {name:['Iðnaður og framleiðsla','Industry & production'],body:['Merkingar þurfa að vinna með vörunni og framleiðsluferlinu. Lýstu yfirborði, notkunaraðstæðum og búnaði svo við getum skoðað rétta útfærslu.','Labels need to work with the product and the production process. Describe the surface, application conditions and equipment so we can explore the right specification.'],action:['Ræða iðnaðarverkefni','Discuss an industrial project']},
 {name:['Fyrirtæki og viðburðir','Business & events'],body:['Plastkort, aðgöngumiðar og spjöld sem miðla skýrum upplýsingum. Við förum yfir útlit, magn, breytileg gögn og frágang með þér.','Plastic cards, admission tickets and passes that communicate clearly. We review design, quantity, variable data and finishing with you.'],action:['Ræða kort eða miða','Discuss cards or tickets']}
];
function industryRows(){return industries.map((item,i)=>`<div class="industry-item"><button class="industry-button" data-industry="${i}" aria-expanded="${state.industry===i}" aria-controls="industry-content-${i}"><span><small>0${i+1}</small>${pair(item.name)}</span><span class="circle" aria-hidden="true">${state.industry===i?'−':'+'}</span></button><div class="industry-body" id="industry-content-${i}" ${state.industry===i?'':'hidden'}><p>${pair(item.body)}</p><button class="arrow-link" data-quote data-context="${esc(pair(item.name))}" style="background:none;border:0;padding:0">${circle}${pair(item.action)}</button></div></div>`).join('');}
function home(){return `<div class="page-enter"><section class="hero container"><div class="hero-intro"><div><div class="eyebrow">${T('Merkingar · Prentun · Umbúðir','Labels · Printing · Packaging')}</div><h1 class="serif">${T('Þín vara.<br><em>Okkar handverk.</em>','Your product.<br><em>Our craft.</em>')}</h1></div><div class="hero-description"><p>${T('Frá hugmynd að áþreifanlegri útkomu. Við aðstoðum við val á efni, prentun og frágangi fyrir merkingar og umbúðir vörunnar þinnar.','From an idea to something you can hold. We help you choose materials, print methods and finishes for your product’s labels and packaging.')}</p><button class="pill" data-quote>${T('Fá tilboð í verkefni','Request a project quote')}${arrow}</button></div></div><div class="hero-photo-wrap"><img class="hero-photo" src="assets/label-design-hero.png" alt="${T('Unnið að hönnun vörumerkingar við tölvu','A designer working on a product label at a computer')}" width="2744" height="1528" fetchpriority="high"></div><div class="photo-caption"><span>${T('Hönnun · Merkingar · Umbúðir','Design · Labels · Packaging')}</span><span>${T('Frá hugmynd að útfærslu','From concept to artwork')}</span></div></section><section class="intro-statement container" id="about"><div class="eyebrow">${T('Þekking frá 1962','Expertise since 1962')}</div><h2 class="serif">${T('Góð merking gerir meira en að sjást. Hún tengir <em>vöruna, vörumerkið og fólkið.</em>','A good label does more than stand out. It connects <em>the product, the brand and the people.</em>')}</h2></section><section class="products container" id="products"><div class="section-heading"><div><div class="eyebrow">${T('Vörur og lausnir','Products and solutions')}</div><h2 class="serif">${T('Rétta lausnin.<br>Réttur frágangur.','The right solution.<br>The right finish.')}</h2></div><p>${T('Skoðaðu verk okkar og fjölbreyttar lausnir í merkingum, prentun og umbúðum. Við vinnum með ólík efni, prentaðferðir og frágang til að mæta þörfum hvers viðskiptavinar. Hvert verkefni tekur mið af vörunni, notkun hennar og ásýnd vörumerkisins — frá fyrstu hugmynd að fullunnu verki.','Explore our work across labels, printing and packaging. We use a range of materials, printing methods and finishes to meet each client’s needs. Every project is shaped around the product, its purpose and the brand behind it — from the first idea to the finished result.')}</p></div><div class="product-grid">${productKeys.map((k,i)=>productCard(k,i,i<2)).join('')}</div><div class="product-helper"><span>${T('Óviss um hvaða lausn hentar vörunni þinni?','Not sure which solution suits your product?')}</span><button data-quote>${T('Fáðu ráðgjöf frá okkur','Get advice from our team')} ↗</button></div></section><section class="industry-section" id="industries"><div class="container"><div class="industry-header"><div><div class="eyebrow">${T('Lausnir eftir notkun','Solutions by application')}</div><h2 class="serif">${T('Falleg að utan.<br><em>Rétt að innan.</em>','Considered outside.<br><em>Right inside.</em>')}</h2></div><p>${T('Útlit og virkni þurfa að vinna saman. Við byrjum á að skilja vöruna, aðstæður hennar og kröfur framleiðslunnar.','Appearance and function need to work together. We start by understanding the product, its conditions and production requirements.')}</p></div><div class="industry-layout"><div class="industry-list">${industryRows()}</div><figure class="industry-visual"><img src="assets/industry-packaging.png" alt="${T('Merktum umbúðum pakkað á bretti í framleiðslu','Labelled packaging being wrapped on a production pallet')}" loading="lazy" width="1772" height="1518"><span class="square" aria-hidden="true"></span><figcaption>${T('Yfirborð. Aðstæður. Ásetning.','Surface. Conditions. Application.')}</figcaption></figure></div><p class="industry-note">${T('Hæfi efna og tæknileg útfærsla eru staðfest fyrir hvert verkefni.','Material suitability and technical specifications are confirmed for each project.')}</p></div></section><section class="craft-section container" id="quality"><figure class="craft-photo"><img src="assets/production.jpg" alt="${T('Starfsfólk Vörumerkingar yfirfer prentverk','Vörumerking staff inspecting printed work')}" loading="lazy" width="1822" height="1080"><figcaption>${T('Úr framleiðslu Vörumerkingar.','From Vörumerking’s production.')}</figcaption></figure><div class="craft-content"><div class="eyebrow">${T('Gæði eru í smáatriðunum','Quality is in the details')}</div><h2 class="serif">${T('Þekkingin<br>fylgir verkinu.','Expertise.<br>At every step.')}</h2><p>${T('Efnisval, prentun og yfirferð skipta öll máli. Reynsla starfsfólks og samtal við viðskiptavin leiða verkefnið frá fyrstu hugmynd að samþykktu verki.','Materials, printing and review all matter. Our team’s experience and a conversation with the customer guide the project from the first idea to approved artwork.')}</p><div class="craft-values"><div><strong>1962</strong><span>${T('Stofnár Vörumerkingar','Vörumerking established')}</span></div><div><strong>${T('Samtal','Dialogue')}</strong><span>${T('Fyrsta skrefið í góðu verki','The first step in good work')}</span></div></div><button class="arrow-link" data-info="quality" style="background:none;border:0;padding:0">${circle}${T('Um gæði og staðfestingar','Quality and documentation')}</button></div></section><section class="process container" id="process"><div class="process-heading"><h2 class="serif">${T('Frá hugmynd að framleiðslu.','From idea to production.')}</h2><div class="eyebrow">${T('Skýrt ferli','A clear process')}</div></div><div class="process-grid">${[
 [['Samtal og tilboð','Advice & quote'],['Segðu okkur frá vörunni, notkun og magni. Við förum yfir valkostina.','Tell us about the product, use and quantity. We explore the options.']],
 [['Gögn og próförk','Artwork & proof'],['Prentgögn eru yfirfarin og útlit samþykkt áður en verk fer í framleiðslu.','Artwork is reviewed and the design approved before production.']],
 [['Framleiðsla','Production'],['Verkið er unnið samkvæmt samþykktri útfærslu og tæknilýsingu.','The work follows the approved specification and artwork.']],
 [['Afhending','Delivery'],['Afhending og næstu skref eru staðfest í samtali við þig.','Delivery and next steps are confirmed with you.']]
 ].map((r,i)=>`<div class="process-step"><div class="process-number"><span>0${i+1}</span><span aria-hidden="true">→</span></div><h3>${pair(r[0])}</h3><p>${pair(r[1])}</p></div>`).join('')}</div></section><div class="container"><section class="artwork-feature"><div><div class="eyebrow">${T('Prentgögn og aðstoð','Artwork and help')}</div><h2 class="serif">${T('Góð gögn.<br>Góð útkoma.','Good artwork.<br>A good result.')}</h2></div><div class="artwork-right"><p>${T('Réttar stærðir, litir og frágangur gagna einfalda vinnuna. Fáðu yfirlit yfir það sem þarf að hafa í huga áður en þú skilar prentgögnum.','Correct dimensions, colours and file preparation make the work easier. See what to consider before delivering your artwork.')}</p><div class="artwork-links"><a class="arrow-link" href="#artwork">${circle}${T('Leiðbeiningar um prentgögn','Artwork guidelines')}</a><button class="arrow-link" data-reorder style="background:none;border:0;padding:0;color:inherit">${circle}${T('Endurpanta verk','Repeat an order')}</button></div></div></section></div></div>`;}

function productPage(key){
 const p=products[key]||products.labels;key=products[key]?key:'labels';
 const specs=p.specs.map(([a,b])=>`<tr><th scope="row">${pair(a)}</th><td>${pair(b)}</td></tr>`).join('');
 return `<div class="subpage container page-enter"><div class="breadcrumbs"><a href="#home">${T('Forsíða','Home')}</a><span>/</span><a href="#products">${T('Vörur','Products')}</a><span>/</span><span>${pair(p.name)}</span></div><section class="detail-intro"><div class="detail-picture ${key}">${productPicture(key)}<span class="sample">${T('Myndræn framsetning · Sýnishorn','Visual representation · Illustrative sample')}</span></div><div class="detail-content"><div class="eyebrow">${T('Vörur og lausnir','Products and solutions')}</div><h1 class="serif">${pair(p.name)}</h1><div class="lead">${pair(p.lead)}</div><p>${pair(p.body)}</p><button class="pill" data-quote="${key}">${T('Fá tilboð','Request a quote')}${arrow}</button><div class="detail-use">${p.tags.map(tag=>`<span class="tag">${pair(tag)}</span>`).join('')}</div></div></section><section class="detail-columns"><div><h2>${T('Valkostir og útfærsla.','Options and specifications.')}</h2><table class="spec-table"><tbody>${specs}</tbody></table></div><aside class="detail-advice"><div class="eyebrow">${T('Við hjálpum þér að velja','We help you choose')}</div><h2 style="margin-top:20px">${T('Þú þarft ekki að<br>vita allt fyrirfram.','You don’t need to<br>know it all yet.')}</h2><p>${T('Byrjaðu á notkun, áætlaðri stærð og magni. Við spyrjum um þau tæknilegu atriði sem skipta máli fyrir þitt verkefni.','Start with the use, approximate size and quantity. We ask about the technical details that matter for your project.')}</p><button class="arrow-link" data-quote="${key}" style="background:none;border:0;padding:0">${circle}${T('Ræða verkefnið','Discuss the project')}</button></aside></section><section class="faq"><h2 class="serif">${T('Gott að vita.','Good to know.')}</h2>${faqMarkup(key)}</section><section class="related"><div class="section-heading"><h2 class="serif" style="font-size:47px">${T('Tengdar lausnir.','Related solutions.')}</h2><a class="arrow-link" href="#products">${T('Allar vörur','All products')}${arrow}</a></div><div class="product-grid">${productKeys.filter(k=>k!==key).slice(0,3).map((k,i)=>productCard(k,i)).join('')}</div></section></div>`;
}
function faqMarkup(key){return [
 [['Þarf ég að skila prentgögnum með tilboðsbeiðni?','Do I need artwork to request a quote?'],['Nei. Þú getur byrjað á lýsingu á vörunni og notkun hennar. Prentgögnum má skila síðar þegar útfærslan hefur verið skýrð.','No. Start with a description of the product and its use. Artwork can follow after the specification is clearer.']],
 [['Hvað þarf að koma fram fyrir tilboð?','What information is useful for a quote?'],['Notkun, áætlað magn, stærð og ósk um afhendingu. Ef þú ert óviss um efnið eða tæknilegar upplýsingar geturðu óskað eftir ráðgjöf.','The intended use, approximate quantity, dimensions and requested delivery timing. If materials or technical details are uncertain, ask for advice.']],
 [['Hvenær er verkið tilbúið til framleiðslu?','When is the job ready for production?'],['Þegar útfærsla, tæknilýsing og viðeigandi próförk hafa verið samþykkt. Innsending beiðni eða upphleðsla gagna jafngildir ekki samþykki til prentunar.','When the specification and required proof have been approved. Submitting a request or uploading artwork does not approve a job for printing.']],
 [['Get ég endurpantað fyrra verk?','Can I repeat a previous order?'],['Já, byrjaðu á vörunúmeri úr fyrri pöntun og tilgreindu hvað hefur breyst. Við staðfestum upplýsingar, verð og afhendingu.','Yes, start with the product reference from a previous order and specify what has changed. We confirm details, pricing and delivery.']]
 ].map(([q,a])=>`<details><summary>${pair(q)}</summary><p>${pair(a)}</p></details>`).join('');}
function artworkPage(){return `<div class="subpage container page-enter"><div class="breadcrumbs"><a href="#home">${T('Forsíða','Home')}</a><span>/</span><span>${T('Prentgögn og aðstoð','Artwork and help')}</span></div><section class="artwork-hero"><div><div class="eyebrow" style="margin-bottom:23px">${T('Prentgögn og aðstoð','Artwork and help')}</div><h1 class="serif">${T('Góð gögn.<br>Góð útkoma.','Good artwork.<br>A good result.')}</h1></div><p>${T('Réttur undirbúningur sparar fyrirhöfn. Notaðu þetta yfirlit til að hefja samtalið og fáðu nákvæmar kröfur fyrir viðkomandi vöru frá forvinnslu.','Good preparation makes the work easier. Use this overview to start the conversation and ask prepress for the exact requirements for your product.')}</p></section><div class="guide-grid"><section class="guide-main"><h2>${T('Áður en þú skilar.','Before you deliver.')}</h2>${[
 [['Stærð og stansform','Dimensions & dieline'],['Staðfestu endanlega stærð, lögun og stansform áður en hönnun er fullgerð. Sniðmát þarf að eiga við vöruna og hafa rétta útgáfu.','Confirm the final dimensions, shape and dieline before completing the design. A template must match the product and the correct revision.']],
 [['Letur og myndir','Fonts & images'],['Letur og tengdar myndir þurfa að vera rétt meðhöndluð. Fáðu leiðbeiningar um samþykkt skráasnið, innfellingu leturs og upplausn.','Fonts and linked images need to be handled correctly. Ask for approved file formats, font embedding and resolution requirements.']],
 [['Litir og blæðing','Colour & bleed'],['Litastillingar og blæðing ráðast af prentaðferð og vöru. Notaðu staðfestar leiðbeiningar fyrir þitt verk.','Colour settings and bleed depend on the printing method and product. Use the approved requirements for your job.']],
 [['Próförk og samþykki','Proof & approval'],['Próförk sýnir lokaútlit. Móttaka skrár er ekki samþykki til framleiðslu; viðeigandi próförk þarf að vera samþykkt sérstaklega.','The proof shows the final appearance. Receiving a file does not approve it for production; the required proof must be approved separately.']]
 ].map(([a,b],i)=>`<div class="guide-step"><span>0${i+1}</span><div><h3>${pair(a)}</h3><p>${pair(b)}</p></div></div>`).join('')}</section><aside class="guide-side"><h2>${T('Réttu gögnin<br>fyrir þitt verk.','The right files<br>for your job.')}</h2><p>${T('Þarftu stansform eða aðstoð við útfærslu? Hafðu samband með vöruflokki og áætlaðri stærð.','Need a dieline or help with the specification? Contact us with the product family and approximate dimensions.')}</p><a href="mailto:vorumerking@vorumerking.is">vorumerking@vorumerking.is ↗</a><div class="upload-preview"><span class="design-chip">${T('Sýnishorn af gagnaskilum','File delivery preview')}</span><label for="artwork-file">${T('Velja skrá til að sjá framsetningu','Choose a file to see the layout')}</label><input id="artwork-file" type="file" multiple accept=".pdf,.ai,.eps,.tif,.tiff,.jpg,.png"><div class="file-info" id="file-info" aria-live="polite"><p>${T('Engin skrá er send eða vistuð á netinu í þessari hönnunartillögu.','No file is sent or stored online in this design concept.')}</p></div></div></aside></div><section class="faq"><h2 class="serif">${T('Algengar spurningar.','Common questions.')}</h2>${faqMarkup('labels')}</section></div>`;}

function render({preserveScroll=false}={}){
 const oldY=window.scrollY;document.documentElement.lang=state.lang;document.title=T('Vörumerking · Merkingar og umbúðir','Vörumerking · Labels and packaging');
 header();footer();const route=location.hash.slice(1);
 document.getElementById('main').innerHTML=route.startsWith('product/')?productPage(route.split('/')[1]):route==='artwork'?artworkPage():home();
 setupVideoHeader(!route.startsWith('product/')&&route!=='artwork');
 if(state.request&&document.getElementById('request-dialog').open)renderRequest();
 if(preserveScroll)requestAnimationFrame(()=>window.scrollTo({top:oldY,behavior:'instant'}));
 else if(route==='artwork'||route.startsWith('product/')||route==='home'||!route)window.scrollTo({top:0,behavior:'instant'});
 else requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView({behavior:'instant'}));
}
function openMenu(){const d=document.getElementById('mobile-menu');d.innerHTML=`<div class="menu-inner"><div class="menu-heading-row"><h2 id="menu-heading">Vörumerking</h2><button class="close-button" data-close="mobile-menu" aria-label="${T('Loka valmynd','Close menu')}">×</button></div><nav class="menu-links">${menuItems().map(([n,k])=>`<a href="#${k}" data-menu-link>${n}</a>`).join('')}</nav><div class="menu-actions"><button class="pill" data-quote>${T('Fá tilboð','Request a quote')}${arrow}</button><button class="pill ghost" data-reorder>${T('Endurpanta','Repeat order')}${arrow}</button><a class="arrow-link" href="#artwork" data-menu-link>${circle}${T('Prentgögn og aðstoð','Artwork and help')}</a></div></div>`;d.showModal();}
function openRequest(product='labels',mode='quote',context=''){
 document.getElementById('mobile-menu').close();state.request={mode,step:mode==='reorder'?2:1,data:{product:products[product]?product:'labels',context},error:''};renderRequest();document.getElementById('request-dialog').showModal();
}
const input=(name,label,type='text',wide=false,required=false,placeholder='')=>{const r=state.request;return `<div class="field ${wide?'wide':''}"><label for="request-${name}">${label}${required?' *':''}</label><input id="request-${name}" name="${name}" type="${type}" value="${esc(r.data[name]||'')}" ${required?'required':''} ${type==='number'?'min="1" step="1"':''} ${type==='email'?'autocomplete="email"':''} placeholder="${esc(placeholder)}"></div>`;};
const select=(name,label,options,wide=false)=>`<div class="field ${wide?'wide':''}"><label for="request-${name}">${label}</label><select id="request-${name}" name="${name}">${options.map(([val,title])=>`<option value="${val}" ${state.request.data[name]===val?'selected':''}>${title}</option>`).join('')}</select></div>`;
function requestFields(){
 const r=state.request;
 if(r.step===1)return `<div class="product-choice">${productKeys.map(k=>`<button type="button" class="choice ${r.data.product===k?'selected':''}" data-product-choice="${k}" aria-pressed="${r.data.product===k}">${pair(products[k].name)}</button>`).join('')}<button type="button" class="choice ${r.data.product==='unsure'?'selected':''}" data-product-choice="unsure" aria-pressed="${r.data.product==='unsure'}">${T('Ég þarf ráðgjöf','Help me choose')}</button></div>`;
 if(r.step===2&&r.mode==='reorder')return `<div class="form-grid">${input('reference',T('Vörunúmer úr fyrri pöntun','Previous product reference'),'text',true,true)}${input('quantity',T('Pantað magn','Quantity'),'number',false,true)}${select('unit',T('Eining','Unit'),[['pieces',T('Stykki','Pieces')],['rolls',T('Rúllur','Rolls')]])}${input('date',T('Ósk um afhendingardag','Requested delivery date'),'date',true)}${select('artwork',T('Eru prentgögn óbreytt?','Is the artwork unchanged?'),[['same',T('Já, óbreytt','Yes, unchanged')],['changed',T('Breytingar þarf','Changes needed')],['unsure',T('Veit ekki','Not sure')]],true)}<div class="field wide"><label for="request-comments">${T('Annað sem þarf að breyta','Other changes')}</label><textarea id="request-comments" name="comments">${esc(r.data.comments||'')}</textarea></div></div>`;
 if(r.step===2)return `<div class="form-grid">${input('use',T('Vara og fyrirhuguð notkun','Product and intended use'),'text',true,false,T('T.d. merking á glerflösku','E.g. a label on a glass bottle'))}${input('width',T('Breidd (mm)','Width (mm)'),'number')}${input('height',T('Hæð (mm)','Height (mm)'),'number')}${input('quantity',T('Áætlað magn','Approximate quantity'),'number')}${select('unit',T('Eining','Unit'),[['pieces',T('Stykki','Pieces')],['rolls',T('Rúllur','Rolls')]])}${r.data.product==='labels'?select('application',T('Ásetning','Application'),[['unsure',T('Veit ekki / þarf ráðgjöf','Not sure / need advice')],['manual',T('Handvirk','Manual')],['machine',T('Vélræn','Machine')]],true):''}${r.data.application==='machine'&&r.data.product==='labels'?`${input('core',T('Kjarnastærð (mm), ef þekkt','Core size (mm), if known'),'number')}${input('roll',T('Hámarksþvermál rúllu (mm)','Maximum roll diameter (mm)'),'number')}`:''}${input('date',T('Ósk um afhendingardag','Requested delivery date'),'date',true)}<div class="field wide"><small>${T('Óviss um stærð eða magn? Reitirnir mega vera auðir. Við aðstoðum við útfærsluna.','Unsure about dimensions or quantity? Leave these blank. We help with the specification.')}</small></div></div>`;
 if(r.step===3)return `<div class="form-grid">${input('company',T('Fyrirtæki','Company'),'text',true)}${input('name',T('Nafn tengiliðs','Contact name'),'text',true,true)}${input('email',T('Netfang','Email'),'email',true,true)}${input('phone',T('Sími, valfrjálst','Phone, optional'),'tel',true)}<div class="field wide"><small>${T('Prentgögn þarf ekki að senda hér. Kennitala kemur síðar ef pöntun eða reikningsgerð krefst hennar.','Artwork does not need to be sent here. A company identifier can follow when ordering or billing requires it.')}</small></div></div>`;
 return '';
}
function requestSummary(){const r=state.request;const data=r.data;const unknown=T('Rætt með ráðgjafa','Discuss with our team');const rows=[];
 if(r.mode==='reorder')rows.push([T('Vörunúmer','Reference'),data.reference]);else rows.push([T('Vara','Product'),products[data.product]?pair(products[data.product].name):T('Þarf ráðgjöf','Need advice')]);
 if(data.context)rows.push([T('Atvinnugrein','Industry'),data.context]);
 if(data.use)rows.push([T('Notkun','Use'),data.use]);
 rows.push([T('Magn','Quantity'),data.quantity?data.quantity+' '+(data.unit==='rolls'?T('rúllur','rolls'):T('stykki','pieces')):unknown]);
 if(data.width||data.height)rows.push([T('Stærð','Size'),`${data.width||'?'} × ${data.height||'?'} mm`]);
 if(data.product==='labels'&&data.application)rows.push([T('Ásetning','Application'),({machine:T('Vélræn','Machine'),manual:T('Handvirk','Manual'),unsure:unknown})[data.application]]);
 if(data.product==='labels'&&data.application==='machine'){if(data.core)rows.push([T('Kjarni','Core'),data.core+' mm']);if(data.roll)rows.push([T('Þvermál rúllu','Roll diameter'),data.roll+' mm']);}
 if(data.artwork)rows.push([T('Prentgögn','Artwork'),({same:T('Óbreytt','Unchanged'),changed:T('Breytingar þarf','Changes needed'),unsure:unknown})[data.artwork]]);
 if(data.comments)rows.push([T('Breytingar','Changes'),data.comments]);
 rows.push([T('Afhending','Delivery'),data.date||T('Staðfest síðar','To be confirmed')]);rows.push([T('Tengiliður','Contact'),data.name||unknown]);rows.push([T('Netfang','Email'),data.email||unknown]);
 return rows.map(([a,b])=>`<div class="summary-row"><span>${a}</span><span>${esc(b)}</span></div>`).join('');
}
function progressSteps(r){
 const labels=r.mode==='reorder'?[T('Fyrra verk','Previous order'),T('Samband','Contact')]:[T('Vara','Product'),T('Verkefni','Project'),T('Samband','Contact')];
 const current=r.step-(r.mode==='reorder'?2:1);
 return `<div class="steps">${labels.map((label,i)=>`<span class="${i===current?'current':''}">0${i+1} ${label}</span>`).join('')}</div>`;
}
function renderRequest(){
 const r=state.request;if(!r)return;const d=document.getElementById('request-dialog');
 const title=r.step===5?T('Ferlið er tilbúið.','That’s the flow.'):r.step===4?T('Yfirfarðu beiðnina.','Review your request.'):r.mode==='reorder'?T('Endurpanta verk.','Repeat an order.'):r.step===1?T('Hvað viltu merkja?','What would you like to make?'):r.step===2?T('Segðu okkur frá verkinu.','Tell us about the project.'):T('Hvernig náum við í þig?','How can we reach you?');
 d.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><div class="eyebrow">${T('Hönnunartillaga · Gagnvirkt ferli','Design concept · Interactive flow')}</div><button class="close-button" data-close="request-dialog" aria-label="${T('Loka','Close')}">×</button></div>${r.step===5?'<div class="done-icon" aria-hidden="true">✓</div>':''}<h2 id="request-heading">${title}</h2><p class="demo-note">${r.step===5?T('Þetta var sýnishorn af ferlinu. Engin beiðni hefur verið send til Vörumerkingar og upplýsingarnar eru ekki vistaðar.','This was a preview of the flow. No request has been sent to Vörumerking and the details are not stored.'):T('Þú ert að prófa útlit og virkni. Beiðnir eru ekki sendar í þessari hönnunartillögu.','You are trying the design and interaction. Requests are not sent in this prototype.')}</p>${r.step<4?progressSteps(r):''}<div id="request-error" class="form-error" role="alert" ${r.error?'':'hidden'}>${esc(r.error)}</div>${r.step<4?`<form id="request-form" novalidate>${requestFields()}<div class="form-actions">${r.step>(r.mode==='reorder'?2:1)?`<button type="button" class="back" data-request-back>${T('Til baka','Back')}</button>`:'<span></span>'}<button type="submit" class="pill">${r.step===3?T('Yfirfara beiðni','Review request'):T('Áfram','Continue')}${arrow}</button></div></form>`:r.step===4?`<div>${requestSummary()}</div><div class="form-actions"><button class="back" data-request-back>${T('Breyta upplýsingum','Edit details')}</button><button class="pill" data-request-done>${T('Ljúka sýnishorni','Finish preview')}${arrow}</button></div>`:`<div class="form-actions"><button class="pill" data-close="request-dialog">${T('Aftur á vefinn','Back to the website')}${arrow}</button></div>`}</div>`;
 d.scrollTop=0;
}
function saveForm(){const form=document.getElementById('request-form');if(form)for(const[k,v]of new FormData(form))state.request.data[k]=v;}
function openInfo(kind){
 let title='',body='';
 if(kind==='quality'){title=T('Gæði með skýru umfangi.','Quality with a clear scope.');body=`<p>${T('Við förum yfir efni, notkun og tæknilegar kröfur fyrir hvert verkefni. Útfærsla og próförk þurfa að vera samþykkt áður en framleiðsla hefst.','We review materials, use and technical requirements for each project. The specification and proof need approval before production starts.')}</p><p>${T('Gæðavottorð og önnur gögn þarf að tengja við nákvæmt umfang, vöru og starfsstöð. Hafðu samband við Vörumerkingu fyrir núverandi skjöl sem eiga við þitt verkefni.','Quality certificates and supporting documents need an exact scope, product and production site. Contact Vörumerking for current documentation relevant to your project.')}</p><p><a href="mailto:vorumerking@vorumerking.is">vorumerking@vorumerking.is</a></p>`;}
 else if(kind==='privacy'){title=T('Um þetta sýnishorn.','About this prototype.');body=`<p>${T('Þessi hönnunartillaga sýnir mögulega framsetningu vefs og eyðublaða. Innsláttur í tilboðs- eða endurpöntunarferli er aðeins í minni vafrans meðan glugginn er opinn. Engar beiðnir eða skrár eru sendar.','This design concept demonstrates a possible website and form layout. Quote and reorder details remain only in browser memory while the dialog is open. No requests or files are sent.')}</p><p>${T('Tungumálaval er vistað í þessum vafra. Engin greiningar- eða auglýsingakerfi eru notuð. Tenglar í tölvupóst og síma opna viðkomandi forrit ef þú velur þá.','Your language choice is saved in this browser. No analytics or advertising systems are used. Email and phone links open their respective applications if selected.')}</p>`;}
 else{title=T('Íslenskt handverk.<br>Ritstýrð framsetning.','Icelandic craft.<br>An editorial presentation.');body=`<p>${T('Útlitið sækir í hlýja myndefnisnotkun, rúmt umbrot og litafleti Travel Connect. Stórar fíngerðar fyrirsagnir, dökkir kaflar og hringlaga örvar sækja innblástur í Reykjastræti.','The design takes warm imagery, generous layouts and colour blocks from Travel Connect. Large fine serif headings, dark sections and circular arrow links draw on Reykjastræti.')}</p><p>${T('Vöruleiðir, tilboð, endurpantanir og gagnaskil byggja á endurhönnunarskýrslunni. Merki og framleiðslumynd koma af núverandi vef Vörumerkingar. Aðalmyndin er myndræn hugmynd, ekki mynd af framleiddum vörum fyrirtækisins.','Product routes, quotes, reorders and artwork delivery follow the redesign report. The logo and production photograph come from Vörumerking’s existing site. The hero image is illustrative, not a photograph of the company’s manufactured products.')}</p><div class="info-palette"><span style="background:var(--navy)"></span><span style="background:var(--brand)"></span><span style="background:#bee4f7"></span><span style="background:var(--lavender)"></span></div><p><a href="https://www.travelconnect.com/" target="_blank" rel="noopener">Travel Connect ↗</a> &nbsp; <a href="https://reykjastraeti.is/" target="_blank" rel="noopener">Reykjastræti ↗</a></p>`;}
 const d=document.getElementById('info-dialog');d.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><div class="eyebrow">Vörumerking</div><button class="close-button" data-close="info-dialog" aria-label="${T('Loka','Close')}">×</button></div><h2 id="info-heading">${title}</h2><div class="info-copy">${body}</div></div>`;d.showModal();
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.getAttribute('href')==='#main'){e.preventDefault();const main=document.getElementById('main');main.focus({preventScroll:true});main.scrollIntoView();return;}
 if(b.hasAttribute('data-quote')){openRequest(b.dataset.quote||'labels','quote',b.dataset.context||'');}
 else if(b.hasAttribute('data-reorder'))openRequest('labels','reorder');
 else if(b.hasAttribute('data-language')){saveForm();state.lang=state.lang==='is'?'en':'is';localStorage.setItem('vm-design-language',state.lang);render({preserveScroll:true});}
 else if(b.hasAttribute('data-menu'))openMenu();
 else if(b.dataset.close){document.getElementById(b.dataset.close).close();if(b.dataset.close==='request-dialog'){state.request=null;document.getElementById('request-dialog').innerHTML='';}}
 else if(b.hasAttribute('data-menu-link'))document.getElementById('mobile-menu').close();
 else if(b.dataset.industry!==undefined){state.industry=Number(b.dataset.industry);document.querySelector('.industry-list').innerHTML=industryRows();document.querySelector(`[data-industry="${state.industry}"]`).focus({preventScroll:true});}
 else if(b.dataset.info)openInfo(b.dataset.info);
 else if(b.dataset.productChoice){state.request.data.product=b.dataset.productChoice;state.request.error='';renderRequest();document.querySelector(`[data-product-choice="${state.request.data.product}"]`).focus();}
 else if(b.hasAttribute('data-request-back')){saveForm();state.request.step=Math.max(state.request.mode==='reorder'?2:1,state.request.step-1);state.request.error='';renderRequest();}
 else if(b.hasAttribute('data-request-done')){state.request.step=5;renderRequest();}
 if(b.tagName==='A'&&b.getAttribute('href')===location.hash&&location.hash&&!location.hash.startsWith('#product/')){const id=location.hash.slice(1);document.getElementById(id)?.scrollIntoView();}
});
document.addEventListener('submit',e=>{if(e.target.id!=='request-form')return;e.preventDefault();saveForm();const form=e.target;if(!form.checkValidity()){state.request.error=T('Yfirfarðu skyldureiti og settu inn gilt netfang þar sem þess er óskað.','Please check the required fields and enter a valid email where requested.');const first=form.querySelector(':invalid');const error=document.getElementById('request-error');error.hidden=false;error.textContent=state.request.error;first?.setAttribute('aria-invalid','true');first?.focus();return;}state.request.error='';state.request.step++;renderRequest();document.getElementById('request-heading').setAttribute('tabindex','-1');document.getElementById('request-heading').focus({preventScroll:true});});
document.addEventListener('change',e=>{
 if(e.target.name==='application'){saveForm();renderRequest();document.getElementById('request-application').focus();}
 if(e.target.id==='artwork-file'){const area=document.getElementById('file-info');area.innerHTML='';for(const file of e.target.files){const p=document.createElement('p');p.textContent=`${file.name} · ${Math.ceil(file.size/1024)} KB`;area.append(p);}const note=document.createElement('p');note.style.marginTop='12px';note.textContent=T('Valið á tækinu þínu. Skrárnar hafa ekki verið sendar.','Selected on your device. The files have not been sent.');area.append(note);}
});
document.getElementById('request-dialog').addEventListener('cancel',()=>{state.request=null;document.getElementById('request-dialog').innerHTML='';});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){d.close();if(d.id==='request-dialog'){state.request=null;d.innerHTML='';}}});
window.addEventListener('hashchange',()=>render());
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
let headerFrame=0;
function setupVideoHeader(enabled){
 document.body.classList.toggle('has-video-header',enabled);
 const intro=document.getElementById('video-intro');
 if(!enabled){intro.innerHTML='';return;}
 // Retain the media element when only the page language changes.
 if(!intro.querySelector('video'))intro.innerHTML=`<section class="video-opening" aria-label="${T('Vörumerking í framleiðslu','Vörumerking in production')}"><video autoplay muted loop playsinline disablepictureinpicture disableremoteplayback preload="metadata" poster="assets/header-poster.jpg?v=cover-2" aria-hidden="true"><source src="assets/header-video.mp4?v=cover-2" type="video/mp4"></video><div class="video-wash" aria-hidden="true"></div><a class="video-scroll" href="#main">${T('Skoða meira','Explore more')}<svg class="scroll-chevron" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></a></section>`;
 const video=intro.querySelector('video');
 video.muted=true;
 video.controls=false;
 video.play().catch(()=>{});
 updateVideoHeader();
 requestAnimationFrame(updateVideoHeader);
}
function updateVideoHeader(){
 headerFrame=0;
 if(!document.body.classList.contains('has-video-header'))return;
 const intro=document.getElementById('video-intro');
 const header=document.getElementById('header');
 const target=header.querySelector('.brand img').getBoundingClientRect();
 const end=Math.max(1,intro.offsetHeight-header.offsetHeight);
 const progress=Math.min(1,Math.max(0,window.scrollY/end));
 const eased=progress*progress*(3-2*progress);
 const t=motionPreference.matches?1:eased;
 const width=Math.min(window.innerWidth*.52,480);
 const height=width*77.23/509.92;
 const x=(window.innerWidth-width)/2;
 const y=(intro.offsetHeight-height)/2;
 const logo=document.getElementById('flying-logo');
 const scale=width/target.width+(1-width/target.width)*t;
 logo.style.width=target.width+'px';
 logo.style.transform=`translate3d(${x+(target.left-x)*t}px,${y+(target.top-y)*t}px,0) scale(${scale})`;
 document.body.style.setProperty('--header-reveal',String(progress>=1?1:0));
 document.body.classList.toggle('video-header-docked',progress>=1);
}
function requestHeaderFrame(){if(!headerFrame)headerFrame=requestAnimationFrame(updateVideoHeader);}
window.addEventListener('scroll',requestHeaderFrame,{passive:true});
window.addEventListener('resize',requestHeaderFrame);
motionPreference.addEventListener('change',()=>setupVideoHeader(document.body.classList.contains('has-video-header')));
document.fonts.ready.then(requestHeaderFrame);

render();
